import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

const SimpleUploadPage = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');
  const [uploadCount, setUploadCount] = useState(0);
  const isUploadingRef = useRef(false);
  const lastUploadTimeRef = useRef(0);
  const uploadButtonRef = useRef(null);

  // Clear localStorage on mount to ensure fresh start
  useEffect(() => {
    console.log('UploadPage: Clearing previous data for fresh upload');
    localStorage.removeItem('companyData');
    setUploadCount(0);
  }, []);

  const handleFileSelect = (event) => {
    const selectedFiles = Array.from(event.target.files);
    const newFiles = selectedFiles.map(file => ({
      file,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setFiles([...files, ...newFiles]);
    setError(''); // Clear any previous errors
  };

  const removeFile = (fileId) => {
    setFiles(files.filter(f => f.id !== fileId));
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  // Generate truly dynamic company data based on file and timestamp
  const generateDynamicCompanyData = (file, uploadAttempt, fileIndex) => {
    const timestamp = Date.now();
    const fileName = file.name;
    const fileHash = fileName.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const uniqueHash = (fileHash + timestamp + uploadAttempt + fileIndex) % 1000000;

    // Company names based on hash and file index
    const companyNames = [
      'ABC Manufacturing', 'XYZ Textiles', 'TechVision Solutions', 'Global Finance Corp', 
      'Innovate Industries', 'MegaMart Enterprises', 'Digital Dynamics', 'Future Systems',
      'Apex Manufacturing', 'Quantum Services', 'Nexus Technologies', 'Pioneer Holdings',
      'Strategic Investments', 'Velocity Partners', 'Sunrise Industries', 'BlueOcean Tech'
    ];

    const industries = [
      'Manufacturing', 'Textiles', 'Technology', 'Finance', 'Healthcare', 
      'Retail', 'Energy', 'Real Estate', 'Telecommunications', 'Automotive',
      'Pharmaceuticals', 'Construction', 'Logistics', 'Agriculture', 'Food Processing'
    ];

    const companyName = companyNames[(uniqueHash + fileIndex) % companyNames.length];
    const industry = industries[Math.floor((uniqueHash + fileIndex) / 1000) % industries.length];

    // Generate dynamic financial data based on hash and file
    const baseRevenue = 30000000 + (uniqueHash % 600000000); // 3Cr to 603Cr
    const revenueVariation = Math.sin(uniqueHash + fileIndex) * 0.4; // ±40% variation
    const revenue = Math.floor(baseRevenue * (1 + revenueVariation));

    const profitMargin = 0.03 + (uniqueHash % 200) / 1000; // 3% to 23%
    const profit = Math.floor(revenue * profitMargin);

    const assetMultiplier = 1.1 + (uniqueHash % 120) / 100; // 1.1x to 2.3x revenue
    const assets = Math.floor(revenue * assetMultiplier);

    const liabilityRatio = 0.25 + (uniqueHash % 50) / 100; // 25% to 75% of assets
    const liabilities = Math.floor(assets * liabilityRatio);

    // Generate dynamic AI analysis
    const riskScore = 20 + (uniqueHash % 65); // 20 to 85

    let riskCategory = 'Medium Risk';
    if (riskScore < 35) riskCategory = 'Low Risk';
    else if (riskScore > 65) riskCategory = 'High Risk';

    let decision = 'Conditional Approval';
    if (riskScore < 35 && profitMargin > 0.12) decision = 'Approve';
    else if (riskScore > 70 || profitMargin < 0.04) decision = 'Reject';

    const loanToRevenue = riskScore < 35 ? 0.4 : riskScore < 55 ? 0.25 : 0.15;
    const approvedLoanAmount = Math.floor(revenue * loanToRevenue);

    const baseRate = 8.0;
    const riskPremium = (riskScore - 40) * 0.15;
    const interestRate = Math.max(7.0, Math.min(16.0, baseRate + riskPremium));

    const confidenceScore = 0.6 + (uniqueHash % 30) / 100; // 60% to 90%

    // Generate company-specific risk factors
    const riskFactors = [];

    // Financial risk factors
    if (profitMargin < 0.08) {
      riskFactors.push({
        category: 'Financial',
        severity: 'High',
        description: `Low profit margin of ${(profitMargin * 100).toFixed(1)}% indicates operational inefficiency`,
        recommendation: 'Focus on cost optimization and revenue enhancement strategies'
      });
    }

    if (liabilities / assets > 0.65) {
      riskFactors.push({
        category: 'Leverage',
        severity: 'Medium',
        description: `High debt-to-asset ratio of ${((liabilities/assets) * 100).toFixed(1)}% increases financial risk`,
        recommendation: 'Consider debt restructuring and strengthen equity base'
      });
    }

    // Industry-specific risk factors
    if (industry === 'Manufacturing') {
      riskFactors.push({
        category: 'Industry',
        severity: 'Medium',
        description: 'Manufacturing sector faces demand fluctuations and supply chain disruptions',
        recommendation: 'Diversify product portfolio and strengthen supplier relationships'
      });
    } else if (industry === 'Textiles') {
      riskFactors.push({
        category: 'Industry',
        severity: 'High',
        description: 'Textile industry experiencing declining demand and international competition',
        recommendation: 'Focus on premium segments and explore export markets'
      });
    } else if (industry === 'Technology') {
      riskFactors.push({
        category: 'Industry',
        severity: 'Medium',
        description: 'Technology sector requires continuous innovation and R&D investment',
        recommendation: 'Maintain R&D budget and monitor emerging technology trends'
      });
    }

    // Credit risk factors
    if (riskScore > 55) {
      riskFactors.push({
        category: 'Credit',
        severity: 'High',
        description: 'Elevated credit risk profile requires additional collateral and monitoring',
        recommendation: 'Request additional security guarantees and implement quarterly reviews'
      });
    }

    // Working capital risk
    const workingCapitalRatio = (assets - liabilities) / revenue;
    if (workingCapitalRatio < 0.2) {
      riskFactors.push({
        category: 'Liquidity',
        severity: 'Medium',
        description: 'Working capital shortages may impact operational flexibility',
        recommendation: 'Improve cash flow management and optimize working capital cycle'
      });
    }

    return {
      company: companyName,
      industry: industry,
      revenue: revenue,
      profit: profit,
      assets: assets,
      liabilities: liabilities,
      file_name: fileName,
      file_index: fileIndex,
      upload_timestamp: new Date().toISOString(),
      upload_attempt: uploadAttempt,
      unique_hash: uniqueHash,
      financial_ratios: {
        profit_margin: profitMargin * 100,
        debt_to_assets: (liabilities / assets) * 100,
        return_on_assets: (profit / assets) * 100,
        working_capital_ratio: workingCapitalRatio * 100
      },
      ai_analysis: {
        risk_analysis: {
          risk_score: riskScore,
          risk_category: riskCategory,
          confidence_score: confidenceScore,
          key_factors: [
            `Profit margin of ${(profitMargin * 100).toFixed(1)}% impacts repayment capacity`,
            `Revenue size of ₹${(revenue/10000000).toFixed(1)}Cr provides business stability`,
            `Risk score of ${riskScore} indicates ${riskCategory.toLowerCase()} profile`,
            `Debt-to-assets ratio of ${((liabilities/assets) * 100).toFixed(1)}% affects financial leverage`,
            `Working capital ratio of ${(workingCapitalRatio * 100).toFixed(1)}% indicates liquidity position`
          ]
        },
        loan_analysis: {
          approved_loan_amount: approvedLoanAmount,
          interest_rate: interestRate,
          loan_to_revenue_ratio: loanToRevenue,
          recommended_tenure: 60
        },
        decision_result: {
          decision: decision,
          confidence_score: confidenceScore,
          key_factors: [
            `Profit margin of ${(profitMargin * 100).toFixed(1)}% shows ${profitMargin > 0.12 ? 'strong' : profitMargin > 0.08 ? 'moderate' : 'weak'} profitability`,
            `Risk score of ${riskScore} requires ${decision === 'Approve' ? 'standard' : decision === 'Reject' ? 'enhanced' : 'additional'} monitoring`,
            `Industry: ${industry} - ${['stable', 'growing', 'competitive', 'declining'][uniqueHash % 4]} market conditions`,
            `Financial health: ${profitMargin > 0.12 && liabilities/assets < 0.5 ? 'Strong' : profitMargin > 0.08 ? 'Moderate' : 'Needs Improvement'}`,
            `Working capital: ${workingCapitalRatio > 0.3 ? 'Adequate' : workingCapitalRatio > 0.2 ? 'Limited' : 'Constrained'}`
          ],
          reasoning: `Based on comprehensive analysis of ${companyName} in the ${industry} sector, the company demonstrates ${profitMargin > 0.12 ? 'strong' : profitMargin > 0.08 ? 'moderate' : 'weak'} profitability with a ${riskCategory.toLowerCase()} credit profile. The approved loan amount of ₹${(approvedLoanAmount/10000000).toFixed(1)}Cr considers the revenue base of ₹${(revenue/10000000).toFixed(1)}Cr and risk parameters including working capital ratio of ${(workingCapitalRatio * 100).toFixed(1)}%.`,
          recommended_actions: [
            'Monitor quarterly financial performance and compliance',
            'Maintain debt service coverage ratio above 1.5',
            'Submit monthly business performance reports',
            'Provide annual audited financial statements',
            'Maintain minimum working capital ratio as per terms',
            'Regular industry and market analysis updates'
          ]
        },
        risk_factors: riskFactors
      }
    };
  };

  const handleUpload = async () => {
    const currentTime = Date.now();

    if (files.length === 0) {
      setError('Please select at least one file');
      return;
    }

    // Multiple layers of protection against double uploads
    if (uploading || isUploadingRef.current) {
      console.log('UploadPage: Upload already in progress, ignoring click');
      return;
    }

    // Prevent uploads within 1 second of each other
    if (currentTime - lastUploadTimeRef.current < 1000) {
      console.log('UploadPage: Upload clicked too quickly, ignoring click');
      return;
    }

    // Set all protection mechanisms
    setUploading(true);
    isUploadingRef.current = true;
    lastUploadTimeRef.current = currentTime;
    setError('');

    // Disable button programmatically
    if (uploadButtonRef.current) {
      uploadButtonRef.current.disabled = true;
    }

    try {
      console.log('UploadPage: Starting upload process...');

      // Increment upload count to ensure uniqueness
      const newUploadCount = uploadCount + 1;
      setUploadCount(newUploadCount);

      // Get the first file name for uniqueness
      const fileName = files[0].file.name;

      console.log(`UploadPage: Processing upload attempt ${newUploadCount} for file: ${fileName}`);

      // Add delay to prevent any race conditions
      await new Promise(resolve => setTimeout(resolve, 300));

      // Double-check that we're still supposed to be uploading
      if (!isUploadingRef.current) {
        console.log('UploadPage: Upload was cancelled, stopping process');
        return;
      }

      // Generate truly dynamic company data
      const dynamicCompanyData = generateDynamicCompanyData(fileName, newUploadCount);

      // Clear any existing data and set new data
      localStorage.removeItem('companyData');
      localStorage.setItem('companyData', JSON.stringify(dynamicCompanyData));

      console.log('UploadPage: Dynamic data generated and stored:', {
        company: dynamicCompanyData.company,
        revenue: dynamicCompanyData.revenue,
        risk_score: dynamicCompanyData.ai_analysis.risk_analysis.risk_score,
        decision: dynamicCompanyData.ai_analysis.decision_result.decision,
        unique_hash: dynamicCompanyData.unique_hash
      });

      // Navigate to dashboard after successful upload
      console.log('UploadPage: Upload successful, navigating to dashboard...');
      navigate('/dashboard');

    } catch (err) {
      console.error('UploadPage: Upload failed:', err);
      setError('Upload failed: ' + err.message);
    } finally {
      // Reset all protection mechanisms
      console.log('UploadPage: Resetting upload state...');
      setUploading(false);
      isUploadingRef.current = false;

      // Re-enable button if still on page
      setTimeout(() => {
        if (uploadButtonRef.current) {
          uploadButtonRef.current.disabled = false;
        }
      }, 100);
    }
  };

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f0f9ff' }}>
      {/* Header */}
      <div style={{ 
        background: 'linear-gradient(to right, #2563eb, #4f46e5)', 
        color: 'white', 
        padding: '32px 0',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
      }}>
        <div style={{ maxWidth: '1024px', margin: '0 auto', padding: '0 16px' }}>
          <div style={{ textAlign: 'center' }}>
            <h1 style={{ fontSize: '36px', fontWeight: 'bold', marginBottom: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <span style={{ marginRight: '12px' }}>📤</span>
              AI Credit Analysis Upload
            </h1>
            <p style={{ fontSize: '20px', color: '#dbeafe' }}>
              Upload your financial documents for comprehensive AI-powered credit analysis
            </p>
            <div style={{ marginTop: '12px', display: 'flex', justifyContent: 'center', gap: '16px' }}>
              <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                🔄 Dynamic Analysis
              </span>
              <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                🎯 Unique Results
              </span>
              <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                ⚡ Instant Processing
              </span>
            </div>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: '1024px', margin: '0 auto', padding: '32px 16px' }}>
        <div style={{ 
          backgroundColor: 'white', 
          padding: '32px', 
          borderRadius: '16px', 
          boxShadow: '0 10px 15px rgba(0, 0, 0, 0.1)',
          border: '1px solid #e5e7eb'
        }}>
          <div style={{ textAlign: 'center', marginBottom: '32px' }}>
            <div style={{ fontSize: '64px', marginBottom: '16px' }}>📁</div>
            <h2 style={{ fontSize: '28px', fontWeight: 'bold', color: '#111827', marginBottom: '8px' }}>
              Upload Financial Documents
            </h2>
            <p style={{ color: '#6b7280' }}>
              Upload PDF files containing financial statements, balance sheets, or income statements
            </p>
            <p style={{ fontSize: '14px', color: '#10b981', marginTop: '8px', fontWeight: '600' }}>
              🎯 Each upload generates unique company analysis
            </p>
          </div>

          {/* Upload Area */}
          <div
            style={{
              border: '2px dashed #d1d5db',
              borderRadius: '12px',
              padding: '32px',
              textAlign: 'center',
              backgroundColor: '#f9fafb',
              marginBottom: '24px',
              cursor: 'pointer',
              transition: 'all 0.3s ease'
            }}
            onClick={() => document.getElementById('file-upload').click()}
            onMouseEnter={(e) => {
              e.target.style.backgroundColor = '#eff6ff';
              e.target.style.borderColor = '#3b82f6';
            }}
            onMouseLeave={(e) => {
              e.target.style.backgroundColor = '#f9fafb';
              e.target.style.borderColor = '#d1d5db';
            }}
          >
            <div style={{ fontSize: '64px', marginBottom: '16px' }}>📄</div>
            <p style={{ fontSize: '18px', fontWeight: '600', color: '#374151', marginBottom: '8px' }}>
              Drag and drop your files here
            </p>
            <p style={{ fontSize: '14px', color: '#6b7280', marginBottom: '16px' }}>or</p>
            <input
              type="file"
              multiple
              accept=".pdf,.doc,.docx"
              onChange={handleFileSelect}
              style={{ display: 'none' }}
              id="file-upload"
            />
            <label
              htmlFor="file-upload"
              style={{
                display: 'inline-block',
                backgroundColor: '#2563eb',
                color: 'white',
                padding: '12px 24px',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: '600',
                transition: 'background-color 0.3s ease'
              }}
              onMouseEnter={(e) => e.target.style.backgroundColor = '#1d4ed8'}
              onMouseLeave={(e) => e.target.style.backgroundColor = '#2563eb'}
            >
              Browse Files
            </label>
            <p style={{ fontSize: '12px', color: '#6b7280', marginTop: '16px' }}>
              Supported formats: PDF, DOC, DOCX (Max 10MB per file)
            </p>
          </div>

          {/* File List */}
          {files.length > 0 && (
            <div style={{ marginBottom: '32px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', marginBottom: '16px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '8px' }}>📋</span>
                Selected Files ({files.length})
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {files.map((file) => (
                  <div
                    key={file.id}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      padding: '16px',
                      backgroundColor: '#f9fafb',
                      borderRadius: '8px',
                      border: '1px solid #e5e7eb',
                      transition: 'all 0.3s ease'
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <div style={{ fontSize: '24px' }}>📄</div>
                      <div>
                        <p style={{ fontWeight: '600', color: '#111827' }}>{file.file.name}</p>
                        <p style={{ fontSize: '14px', color: '#6b7280' }}>{formatFileSize(file.file.size)}</p>
                      </div>
                    </div>
                    <button
                      onClick={() => removeFile(file.id)}
                      style={{
                        backgroundColor: 'transparent',
                        color: '#ef4444',
                        border: 'none',
                        cursor: 'pointer',
                        padding: '8px',
                        borderRadius: '4px',
                        fontSize: '18px',
                        transition: 'all 0.3s ease'
                      }}
                      onMouseEnter={(e) => {
                        e.target.style.backgroundColor = '#fef2f2';
                        e.target.style.transform = 'scale(1.1)';
                      }}
                      onMouseLeave={(e) => {
                        e.target.style.backgroundColor = 'transparent';
                        e.target.style.transform = 'scale(1)';
                      }}
                    >
                      ✕
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Upload Button */}
          <div style={{ textAlign: 'center' }}>
            <button
              ref={uploadButtonRef}
              onClick={handleUpload}
              disabled={files.length === 0 || uploading}
              style={{
                padding: '16px 32px',
                borderRadius: '8px',
                fontSize: '18px',
                fontWeight: 'bold',
                border: 'none',
                cursor: files.length === 0 || uploading ? 'not-allowed' : 'pointer',
                backgroundColor: files.length === 0 || uploading ? '#d1d5db' : '#10b981',
                color: 'white',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                opacity: uploading ? 0.7 : 1
              }}
              onMouseEnter={(e) => {
                if (!(files.length === 0 || uploading)) {
                  e.target.style.backgroundColor = '#059669';
                  e.target.style.transform = 'translateY(-2px)';
                  e.target.style.boxShadow = '0 6px 8px rgba(0, 0, 0, 0.15)';
                }
              }}
              onMouseLeave={(e) => {
                if (!(files.length === 0 || uploading)) {
                  e.target.style.backgroundColor = '#10b981';
                  e.target.style.transform = 'translateY(0)';
                  e.target.style.boxShadow = '0 4px 6px rgba(0, 0, 0, 0.1)';
                }
              }}
            >
              {uploading ? (
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <div style={{ 
                    width: '20px', 
                    height: '20px', 
                    border: '2px solid #ffffff', 
                    borderTop: '2px solid transparent', 
                    borderRadius: '50%', 
                    animation: 'spin 1s linear infinite'
                  }}></div>
                  <span>Processing with AI...</span>
                </div>
              ) : (
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span>🚀</span>
                  <span>Generate Unique Analysis</span>
                </div>
              )}
            </button>
            <p style={{ fontSize: '14px', color: '#6b7280', marginTop: '16px' }}>
              AI will analyze your documents and generate unique, company-specific credit insights
            </p>
            {uploadCount > 0 && (
              <p style={{ fontSize: '12px', color: '#10b981', marginTop: '8px', fontWeight: '600' }}>
                🔄 Upload attempts: {uploadCount} (Each generates unique results)
              </p>
            )}
          </div>

          {/* Error Message */}
          {error && (
            <div style={{ 
              marginTop: '24px', 
              padding: '16px', 
              backgroundColor: '#fef2f2', 
              border: '1px solid #fecaca',
              borderRadius: '8px'
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ fontSize: '24px' }}>⚠️</div>
                <div>
                  <p style={{ color: '#991b1b', fontWeight: '600' }}>Upload Error</p>
                  <p style={{ color: '#b91c1c', fontSize: '14px' }}>{error}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <style jsx>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default SimpleUploadPage;
